      {"t":"type","p":"the water","a":["l'acqua"],"hint":"acqua · starts with a vowel","x":["la"],"why":"acqua is feminine and starts with a vowel, so la becomes l'."},
      {"t":"type","p":"the students (all men)","a":["gli studenti"],"hint":"studente · more than one","x":["i"],"why":"studenti is masculine plural and starts with s + consonant: gli."},
      {"t":"type","p":"an orange soda","a":["un'aranciata"],"hint":"aranciata · starts with a vowel","x":["una"],"why":"Before a vowel, una drops its a and an apostrophe takes its place: un'aranciata."}
