      {"t":"order","p":"It's three o'clock.","a":["Sono","le","tre"],"x":["È","la"],"why":"Sono le tre: plural, feminine le, as in le ore."},
      {"t":"order","p":"How much are they?","a":["Quanto","costano?"],"x":["costa?"],"why":"Plural subject (more than one thing), so the verb is costano."},
      {"t":"order","p":"May 1","a":["il","primo","maggio"],"x":["uno"],"why":"The first of the month is il primo; other days use the plain number."},
      {"t":"fill","q":"Quanto __ i biglietti?","p":"How much are the tickets?","a":["costano"],"o":["costa","costi","costate"],"why":"i biglietti is plural, so the verb ending matches the subject: costano."},
      {"t":"fill","q":"__ le sette.","p":"It's seven o'clock.","a":["Sono"],"o":["È","C'è","Ha"],"why":"From two o'clock on, sono le: ore is feminine plural."},
      {"t":"fill","q":"Ho __ anni.","p":"I'm twenty-eight.","a":["ventotto"],"o":["ventiotto","vent'otto","ventotta"],"why":"venti drops its i before otto, with no apostrophe: ventotto."},
      {"t":"type","p":"It's one o'clock.","a":["È l'una."],"hint":"essere · una · one o'clock is a single hour","x":["Sono"],"why":"una is singular, so the verb is è, not sono.","strict":true},
      {"t":"type","p":"two pizzas","a":["due pizze"],"hint":"due (two) · pizza","x":["pizza"],"why":"Plural noun: pizza becomes pizze after due."},
      {"t":"type","p":"How much are the shoes?","a":["Quanto costano le scarpe?","Le scarpe quanto costano?"],"hint":"quanto · costare · scarpa","x":["costa"],"why":"le scarpe is plural, so the verb ending matches the subject: costano."}
